711	/****************************************************************************
712	 * Private Functions - DMA Descriptor Management
713	 ****************************************************************************/
714	
715	static int alloc_dma(struct sg2000_eth_priv_s *priv)
716	{
717	  int i;
718	
719	  /* Descriptors and buffers MUST be aligned to the C906 cache-line
720	   * size (64 bytes, ARCH_DMA_MINALIGN) to prevent cache-line sharing
721	   * between adjacent descriptors/buffers, which would cause data
722	   * corruption when CPU and DMA write to different entities that
723	   * share the same cache line.
724	   */
725	
726	  priv->tx_desc = kmm_memalign(64, TX_RING_SIZE *
727	                                sizeof(struct sg2000_dma_desc_s));
728	  priv->rx_desc = kmm_memalign(64, RX_RING_SIZE *
729	                                sizeof(struct sg2000_dma_desc_s));
730	
731	  if (!priv->tx_desc || !priv->rx_desc)
732	    {
733	      return -ENOMEM;
734	    }
735	
736	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
737	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
738	
739	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
740	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
741	   */
742	
743	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
744	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
745	
746	  for (i = 0; i < TX_RING_SIZE; i++)
747	    {
748	      priv->tx_buf[i] = kmm_memalign(64, TX_BUF_SIZE);
749	      if (!priv->tx_buf[i])
750	        {
751	          return -ENOMEM;
752	        }
753	
754	      priv->tx_pkt[i] = NULL;
755	    }
756	
757	  for (i = 0; i < RX_RING_SIZE; i++)
758	    {
759	      priv->rx_buf[i] = kmm_memalign(64, RX_BUF_SIZE);
760	      if (!priv->rx_buf[i])
761	        {
762	          return -ENOMEM;
763	        }
764	    }
765	
766	  return 0;
767	}
768	
769	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
770	{
771	  uintptr_t base = priv->gmac_base;
772	  int i;
773	  int last;
774	
775	  /* Program DMA Bus Mode register with operational parameters.
776	   * After dma_soft_reset() all bits are cleared; PBL (burst length)
777	   * MUST be programmed for DMA transfers to work.  Use PBL=8
778	   * matching the device tree snps,txpbl/snps,rxpbl settings.
779	   * ATDS=0 selects 16-byte descriptors.
780	   */
781	
782	  putreg32(DMA_PBL_8 | DMA_FB | DMA_AAL, base + DMA_BUS_MODE);
783	
784	  /* Initialize TX descriptors.  The last descriptor has TER (End of Ring)
785	   * set so DWMAC1000 wraps back to the ring base address.
786	   */
787	
788	  last = TX_RING_SIZE - 1;
789	  for (i = 0; i < TX_RING_SIZE; i++)
790	    {
791	      priv->tx_desc[i].des0 = (i == last) ? TX_DESC_TER : 0;
792	      priv->tx_desc[i].des1 = 0;
793	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
794	      priv->tx_desc[i].des3 = 0;
795	      priv->tx_pkt[i] = NULL;
796	    }
797	
798	  /* Flush TX descriptor ring so DMA sees the initialized state */
799	
800	  dcache_clean_range((uintptr_t)priv->tx_desc,
801	                     (uintptr_t)(priv->tx_desc + TX_RING_SIZE));
802	
803	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write).
804	   * The last descriptor has RER (End of Ring) set so DWMAC1000 wraps.
805	   */
806	
807	  last = RX_RING_SIZE - 1;
808	  for (i = 0; i < RX_RING_SIZE; i++)
809	    {
810	      priv->rx_desc[i].des0 = DESC_OWN | ((i == last) ? RX_DESC_RER : 0);
811	      priv->rx_desc[i].des1 = RX_BUF_SIZE;
812	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
813	      priv->rx_desc[i].des3 = 0;
814	    }
815	
816	  /* Flush RX descriptor ring and buffers: DMA will read descriptors
817	   * and write data into the buffers.  Write back the descriptors so
818	   * DMA sees OWN=1.  Also flush RX buffers to ensure any stale cache
819	   * lines are written back before DMA overwrites them.
820	   */
821	
822	  dcache_clean_range((uintptr_t)priv->rx_desc,
823	                     (uintptr_t)(priv->rx_desc + RX_RING_SIZE));
824	
825	  for (i = 0; i < RX_RING_SIZE; i++)
826	    {
827	      dcache_flush_range((uintptr_t)priv->rx_buf[i],
828	                         (uintptr_t)priv->rx_buf[i] + RX_BUF_SIZE);
829	    }
830	
831	  priv->tx_cur = 0;
832	  priv->tx_dirty = 0;
833	  priv->rx_cur = 0;
834	
835	  /* Program DWMAC1000 flat DMA registers.
836	   * DWMAC1000 has NO ring-length registers; wrapping uses TER/RER bits.
837	   * DWMAC1000 has NO channel concept; all registers are flat at 0x1000+.
838	   */
839	
840	  putreg32(priv->tx_desc_phys, base + DMA_TX_BASE_ADDR);
841	  putreg32(priv->rx_desc_phys, base + DMA_RCV_BASE_ADDR);
842	
843	  /* Clear any pending interrupts before enabling them */
844	
845	  putreg32(0x1ffff, base + DMA_STATUS);
846	  putreg32(DMA_INTR_DEFAULT_MASK, base + DMA_INTR_ENA);
847	
848	  syslog(LOG_INFO, "sg2000_eth: DMA init done "
849	         "tx_desc=0x%08" PRIX32 " rx_desc=0x%08" PRIX32
850	         " tx_buf0=0x%08" PRIX32 " rx_buf0=0x%08" PRIX32 "\n",
851	         priv->tx_desc_phys, priv->rx_desc_phys,
852	         (uint32_t)(uintptr_t)priv->tx_buf[0],
853	         (uint32_t)(uintptr_t)priv->rx_buf[0]);
854	}
