856	/****************************************************************************
857	 * Private Functions - MAC and DMA Control
858	 ****************************************************************************/
859	
860	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
861	{
862	  uint32_t hi;
863	  uint32_t lo;
864	
865	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
866	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
867	
868	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
869	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
870	}
871	
872	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
873	{
874	  uintptr_t gmac_base = priv->gmac_base;
875	  uint32_t v;
876	
877	  /* Configure MAC based on PHY negotiation results */
878	
879	  v = GMAC_CORE_INIT;
880	  if (priv->speed == 100)
881	    {
882	      v |= GMAC_CONFIG_FES;   /* 100M */
883	    }
884	
885	  if (priv->duplex)
886	    {
887	      v |= GMAC_CONFIG_DM;    /* Full duplex */
888	    }
889	
890	  putreg32(v, gmac_base + GMAC_CONFIG);
891	
892	  /* Packet filter: pass multicast + broadcast + unicast to us */
893	
894	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
895	           gmac_base + GMAC_PACKET_FILTER);
896	
897	  /* Clear any pending MAC interrupts */
898	
899	  putreg32(0xffffffff, gmac_base + GMAC_INT_STATUS);
900	
901	  /* Enable MAC interrupts */
902	
903	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_EN);
904	
905	  /* Flush TX and RX FIFOs before enabling MAC/DMA */
906	
907	  putreg32(0, gmac_base + 0x0048);  /* GMAC_TX_FLUSH */
908	  putreg32(0, gmac_base + 0x004c);  /* GMAC_RX_FLUSH */
909	
910	  /* Enable MAC TX and RX */
911	
912	  v = getreg32(gmac_base + GMAC_CONFIG);
913	  putreg32(v | GMAC_CONFIG_TE | GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);
914	
915	  /* Start TX DMA via DWMAC1000 DMA_CONTROL (CSR6, 0x1018).
916	   * Bit 13 = ST (Start Transmit), Bit 0 = SR (Start Receive).
917	   * Start TX first; RX will be started after a short delay to avoid
918	   * race conditions where RX DMA tries to use descriptors before
919	   * the TX path is fully ready.
920	   */
921	
922	  v = getreg32(gmac_base + DMA_CONTROL);
923	  putreg32(v | DMA_CONTROL_ST, gmac_base + DMA_CONTROL);
924	  up_udelay(10);
925	
926	  v = getreg32(gmac_base + DMA_CONTROL);
927	  putreg32(v | DMA_CONTROL_SR, gmac_base + DMA_CONTROL);
928	
929	  syslog(LOG_INFO, "sg2000_eth: DMA started "

1180	/****************************************************************************
1181	 * Name: netdriver_ifup
1182	 *
1183	 * Description:
1184	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1185	 *
1186	 ****************************************************************************/
1187	
1188	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1189	{
1190	  FAR struct sg2000_eth_priv_s *priv =
1191	      (FAR struct sg2000_eth_priv_s *)dev;
1192	  int ret;
1193	
1194	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1195	
1196	  /* Ensure GMAC clocks and resets are configured */
1197	
1198	  gmac_clock_enable();
1199	
1200	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1201	
1202	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1203	
1204	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1205	  up_mdelay(10);
1206	
1207	  ret = mdio_verify_phy(priv->gmac_base);
1208	  if (ret < 0)
1209	    {
1210	      nerr("ERROR: TRM legacy MDIO PHY not responding: %d\n", ret);
1211	      return ret;
1212	    }
1213	
1214	  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO operational "
1215	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1216	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_ADDR),
1217	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_DATA));
1218	
1219	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1220	
1221	  ret = phy_config_init(priv);
1222	  if (ret < 0)
1223	    {
1224	      nerr("ERROR: PHY init failed: %d\n", ret);
1225	      return ret;
1226	    }
1227	
1228	  ret = dma_soft_reset(priv->gmac_base);
1229	  if (ret < 0)
1230	    {
1231	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1232	             "diagnostics: %d\n", ret);
1233	      return ret;
1234	    }
1235	
1236	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1237	    {
1238	      ret = alloc_dma(priv);
1239	      if (ret < 0)
1240	        {
1241	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1242	          return ret;
1243	        }
1244	    }
1245	
1246	  init_desc_and_dma(priv);
1247	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1248	  start_mac_and_dma(priv);
1249	  rx_doorbell(priv);
1250	
1251	  up_enable_irq(priv->irq);
1252	  netdev_lower_carrier_on(dev);
1253	
1254	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1255	         priv->speed, priv->duplex ? "Full" : "Half");
1256	
1257	  return OK;
1258	}
