1260	/****************************************************************************
1261	 * Name: netdriver_ifdown
1262	 *
1263	 * Description:
1264	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1265	 *
1266	 ****************************************************************************/
1267	
1268	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1269	{
1270	  FAR struct sg2000_eth_priv_s *priv =
1271	      (FAR struct sg2000_eth_priv_s *)dev;
1272	  uint32_t v;
1273	
1274	  up_disable_irq(priv->irq);
1275	
1276	  /* Stop TX and RX DMA via DWMAC1000 DMA_CONTROL (CSR6, 0x1018).
1277	   * Bit 13 = ST (Start Transmit), Bit 0 = SR (Start Receive).
1278	   */
1279	
1280	  v = getreg32(priv->gmac_base + DMA_CONTROL);
1281	  putreg32(v & ~(DMA_CONTROL_ST | DMA_CONTROL_SR),
1282	           priv->gmac_base + DMA_CONTROL);
1283	
1284	  /* Disable MAC TX/RX */
1285	
1286	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1287	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1288	           priv->gmac_base + GMAC_CONFIG);
1289	
1290	  netdev_lower_carrier_off(dev);
1291	
1292	  ninfo("netdriver_ifdown: interface down\n");
1293	
1294	  return OK;
1295	}
