1297	/****************************************************************************
1298	 * Name: netdriver_transmit
1299	 *
1300	 * Description:
1301	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1302	 *   The driver takes ownership of the netpkt and MUST free it after TX
1303	 *   completion (or on error).
1304	 *
1305	 *   Returned Value:
1306	 *     OK on success (pkt queued for TX); negated errno on failure.
1307	 *
1308	 ****************************************************************************/
1309	
1310	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1311	                               FAR netpkt_t *pkt)
1312	{
1313	  FAR struct sg2000_eth_priv_s *priv =
1314	      (FAR struct sg2000_eth_priv_s *)dev;
1315	  unsigned int len = netpkt_getdatalen(dev, pkt);
1316	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1317	  const uint8_t *data;
1318	  int ret;
1319	
1320	  if (len > SG2000_ETH_BUFSIZE)
1321	    {
1322	      nerr("ERROR: TX packet too large: %u\n", len);
1323	      netpkt_free(dev, pkt, NETPKT_TX);
1324	      return -E2BIG;
1325	    }
1326	
1327	  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */
1328	
1329	  if (netpkt_is_fragmented(pkt))
1330	    {
1331	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1332	      data = tmp_buf;
1333	    }
1334	  else
1335	    {
1336	      data = netpkt_getdata(dev, pkt);
1337	      if (!data)
1338	        {
1339	          nerr("ERROR: netpkt_getdata returned NULL\n");
1340	          netpkt_free(dev, pkt, NETPKT_TX);
1341	          return -EINVAL;
1342	        }
1343	    }
1344	
1345	  /* Send via DMA */
1346	
1347	  ret = hw_transmit(priv, data, len);
1348	  if (ret < 0)
1349	    {
1350	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1351	      netpkt_free(dev, pkt, NETPKT_TX);
1352	      return ret;
1353	    }
1354	
1355	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1356	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1357	   */
1358	
1359	  {
1360	    irqstate_t flags = up_irq_save();
1361	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1362	
1363	    priv->tx_pkt[slot] = pkt;
1364	    up_irq_restore(flags);
1365	  }
1366	
1367	  return OK;
1368	}
