1370	/****************************************************************************
1371	 * Name: netdriver_receive
1372	 *
1373	 * Description:
1374	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1375	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1376	 *   NULL if no more packets are available.
1377	 *
1378	 *   Returned Value:
1379	 *     A netpkt_t * containing the received packet, or NULL.
1380	 *
1381	 ****************************************************************************/
1382	
1383	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1384	{
1385	  FAR struct sg2000_eth_priv_s *priv =
1386	      (FAR struct sg2000_eth_priv_s *)dev;
1387	  FAR netpkt_t *pkt = NULL;
1388	  struct sg2000_dma_desc_s *desc;
1389	  uint32_t status;
1390	  int frame_len;
1391	  int ret;
1392	
1393	  /* Check if there is a completed RX descriptor.
1394	   * Invalidate the descriptor cache line first so we read the status
1395	   * that DMA wrote back (OWN bit, frame length), not stale cached data.
1396	   */
1397	
1398	  desc = &priv->rx_desc[priv->rx_cur];
1399	  dcache_invalidate_range((uintptr_t)desc,
1400	                          (uintptr_t)desc +
1401	                          sizeof(struct sg2000_dma_desc_s));
1402	
1403	  if (desc->des0 & DESC_OWN)
1404	    {
1405	      /* DMA still owns it, no packet ready yet.
1406	       * This can happen if rxready was signaled for a previous packet
1407	       * that was already consumed, or in edge cases.
1408	       */
1409	
1410	      return NULL;
1411	    }
1412	
1413	  status = desc->des0;
1414	
1415	  /* Check for errors */
1416	
1417	  if (status & RX_DESC_ES)
1418	    {
1419	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1420	      goto refill;
1421	    }
1422	
1423	  /* Get frame length (includes FCS which we strip) */
1424	
1425	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - ETH_FCSSLEN;
1426	
1427	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1428	    {
1429	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1430	      goto refill;
1431	    }
1432	
1433	  /* Invalidate the RX data buffer so we read the data that DMA wrote,
1434	   * not stale cached data from a previous use of this buffer.
1435	   */
1436	
1437	  dcache_invalidate_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1438	                          (uintptr_t)priv->rx_buf[priv->rx_cur] +
1439	                          RX_BUF_SIZE);

960	  putreg32(0, priv->gmac_base + DMA_RCV_POLL_DEMAND);
961	}
