963	/****************************************************************************
964	 * Private Functions - Hardware Transmit
965	 ****************************************************************************/
966	
967	static int hw_transmit(struct sg2000_eth_priv_s *priv,
968	                       const uint8_t *data, int len)
969	{
970	  unsigned int idx = priv->tx_cur;
971	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
972	  irqstate_t flags;
973	
974	  /* Check if the ring is full */
975	
976	  if (desc->des0 & DESC_OWN)
977	    {
978	      return -EBUSY;
979	    }
980	
981	  /* Copy data to DMA TX buffer */
982	
983	  memcpy(priv->tx_buf[idx], data, len);
984	
985	  /* Write back the TX buffer so DMA can see the packet data.
986	   * Without this, the CPU's cache may hold dirty lines that the
987	   * non-coherent DMA engine cannot see.
988	   */
989	
990	  dcache_clean_range((uintptr_t)priv->tx_buf[idx],
991	                     (uintptr_t)priv->tx_buf[idx] + len);
992	
993	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
994	  desc->des1 = len;
995	
996	  /* OWN | First Segment | Last Segment | Interrupt on Completion.
997	   * Preserve TER (End of Ring) bit for the last descriptor so the
998	   * DWMAC1000 DMA engine wraps back to the ring base address.
999	   */
1000	
1001	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
1002	               ((idx == (TX_RING_SIZE - 1)) ? TX_DESC_TER : 0) |
1003	               (len & RX_DESC_FL_MASK);
1004	
1005	  /* Write back the descriptor so DMA sees OWN=1 and the buffer address.
1006	   * The fence ensures the stores are ordered before the doorbell write.
1007	   */
1008	
1009	  dcache_clean_range((uintptr_t)desc,
1010	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1011	  __asm__ volatile ("fence w,w" ::: "memory");
1012	
1013	  flags = up_irq_save();
1014	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1015	  tx_doorbell(priv);
1016	  up_irq_restore(flags);
1017	
1018	  syslog(LOG_INFO, "sg2000_eth: TX %u bytes, desc[%u] des0=0x%08" PRIX32
1019	         " des1=0x%08" PRIX32 " des2=0x%08" PRIX32
1020	         " dma_status=0x%08" PRIX32 "\n",
1021	         len, idx, desc->des0, desc->des1, desc->des2,
1022	         getreg32(priv->gmac_base + DMA_STATUS));
1023	
1024	  return 0;
1025	}
1026	
1027	/****************************************************************************
1028	 * Private Functions - TX Cleanup (called from ISR on TX complete)
1029	 ****************************************************************************/
1030	
1031	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
1032	{
1033	  irqstate_t flags = up_irq_save();
1034	
1035	  while (priv->tx_dirty != priv->tx_cur)
1036	    {
1037	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
1038	
1039	      /* Invalidate the descriptor cache line so we read the status
1040	       * that DMA wrote back, not stale cached data.
1041	       */
1042	
1043	      dcache_invalidate_range((uintptr_t)desc,
1044	                              (uintptr_t)desc +
1045	                              sizeof(struct sg2000_dma_desc_s));
1046	
1047	      if (desc->des0 & DESC_OWN)
1048	        {
1049	          /* Still owned by DMA, stop */
1050	
1051	          break;
1052	        }
1053	
1054	      /* Check for TX errors */
1055	
1056	      if (desc->des0 & TX_DESC_ES)
1057	        {
1058	          nerr("ERROR: TX error, status=0x%08" PRIX32 "\n", desc->des0);
1059	        }
1060	
1061	      /* Free the netpkt if we have one tracked for this slot */
1062	
1063	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
1064	        {
1065	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
1066	          priv->tx_pkt[priv->tx_dirty] = NULL;
1067	
1068	          /* Notify upper half that TX is done */
1069	
1070	          netdev_lower_txdone(&priv->dev);
1071	        }
1072	
1073	      /* Release descriptor: clear des0 so it can be reused. */
1074	
1075	      desc->des0 = 0;
1076	
1077	      /* Write back the cleared descriptor so DMA doesn't see stale OWN */
1078	
1079	      dcache_clean_range((uintptr_t)desc,
1080	                         (uintptr_t)desc +
1081	                         sizeof(struct sg2000_dma_desc_s));
1082	
1083	      /* Move to next descriptor */
1084	
1085	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1086	    }
1087	
1088	  up_irq_restore(flags);
