1092	 * Private Functions - ISR
1093	 ****************************************************************************/
1094	
1095	static int sg2000_eth_isr(int irq, void *context, void *arg)
1096	{
1097	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1098	  uintptr_t base = priv->gmac_base;
1099	  uint32_t status;
1100	  uint32_t intr_en;
1101	  uint32_t mac;
1102	
1103	  /* Clear MAC interrupts */
1104	
1105	  mac = getreg32(base + GMAC_INT_STATUS);
1106	  if (mac)
1107	    {
1108	      putreg32(mac, base + GMAC_INT_STATUS);
1109	    }
1110	
1111	  /* Read DWMAC1000 DMA Status (CSR5, 0x1014) masked by enabled interrupts */
1112	
1113	  intr_en = getreg32(base + DMA_INTR_ENA);
1114	  status = getreg32(base + DMA_STATUS) & intr_en;
1115	
1116	  if (status & (DMA_STATUS_TI | DMA_STATUS_RI | DMA_STATUS_NIS |
1117	                DMA_STATUS_AIS | DMA_STATUS_FBI | DMA_STATUS_TPS |
1118	                DMA_STATUS_RPS | DMA_STATUS_RBU))
1119	    {
1120	      syslog(LOG_INFO, "sg2000_eth: ISR dma_status=0x%08" PRIX32
1121	             " intr_en=0x%08" PRIX32 " mac_int=0x%08" PRIX32 "\n",
1122	             getreg32(base + DMA_STATUS), intr_en, mac);
1123	    }
1124	
1125	  if (!status)
1126	    {
1127	      return OK;
1128	    }
1129	
1130	  /* Write-1-to-clear the status bits */
1131	
1132	  putreg32(status, base + DMA_STATUS);
1133	
1134	  if (status & DMA_STATUS_NIS)
1135	    {
1136	      /* Normal interrupt */
1137	
1138	      if (status & DMA_STATUS_RI)
1139	        {
1140	          /* RX complete: notify upper half that packets are ready.
1141	           * The upper half will call our receive() callback to get them.
1142	           */
1143	
1144	          netdev_lower_rxready(&priv->dev);
1145	        }
1146	
1147	      if (status & DMA_STATUS_TI)
1148	        {
1149	          /* TX complete: cleanup descriptors and notify upper half */
1150	
1151	          tx_cleanup(priv);
1152	        }
1153	    }
1154	
1155	  if (status & DMA_STATUS_AIS)
1156	    {
1157	      /* Abnormal interrupt */
1158	
1159	      nerr("ERROR: DMA Abnormal: 0x%08" PRIX32 "\n", status);
1160	
1161	      if (status & DMA_STATUS_RBU)
1162	        {
1163	          nerr("ERROR: RX Buffer Unavailable\n");
1164	        }
1165	
1166	      if (status & DMA_STATUS_TPS)
1167	        {
1168	          nerr("ERROR: TX Process Stopped\n");
1169	        }
1170	
1171	      if (status & DMA_STATUS_FBI)
1172	        {
1173	          nerr("ERROR: Fatal Bus Error\n");
1174	        }
1175	    }
1176	
1177	  return OK;
1178	}
