1430	      goto refill;
1431	    }
1432	
1433	  /* Invalidate the RX data buffer so we read the data that DMA wrote,
1434	   * not stale cached data from a previous use of this buffer.
1435	   */
1436	
1437	  dcache_invalidate_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1438	                          (uintptr_t)priv->rx_buf[priv->rx_cur] +
1439	                          RX_BUF_SIZE);
1440	
1441	  /* Allocate a netpkt for the received data */
1442	
1443	  pkt = netpkt_alloc(dev, NETPKT_RX);
1444	  if (!pkt)
1445	    {
1446	      nerr("ERROR: netpkt_alloc failed\n");
1447	      goto refill;
1448	    }
1449	
1450	  /* Copy data from DMA RX buffer into the netpkt */
1451	
1452	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1453	  if (ret < 0)
1454	    {
1455	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1456	      netpkt_free(dev, pkt, NETPKT_RX);
1457	      goto refill;
1458	    }
1459	
1460	  ninfo("RX packet: %d bytes\n", frame_len);
1461	
1462	refill:
1463	  /* Return the descriptor to DMA (set OWN=1).
1464	   * Re-set the buffer address in des2 in case DMA overwrote it,
1465	   * and flush the buffer to ensure clean state before DMA writes.
1466	   * Preserve RER (End of Ring) bit for the last descriptor.
1467	   */
1468	
1469	  desc->des0 = DESC_OWN |
1470	               ((priv->rx_cur == (RX_RING_SIZE - 1)) ? RX_DESC_RER : 0);
1471	  desc->des1 = RX_BUF_SIZE;
1472	  desc->des2 = (uint32_t)(uintptr_t)priv->rx_buf[priv->rx_cur];
1473	
1474	  /* Flush the RX buffer before handing it back to DMA:
1475	   * write back + invalidate so the buffer is clean for DMA to write into.
1476	   */
1477	
1478	  dcache_flush_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1479	                     (uintptr_t)priv->rx_buf[priv->rx_cur] + RX_BUF_SIZE);
1480	
1481	  /* Write back the descriptor so DMA sees OWN=1 and the new buffer */
1482	
1483	  dcache_clean_range((uintptr_t)desc,
1484	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1485	
1486	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1487	  rx_doorbell(priv);
1488	
1489	  return pkt;
1490	}
