218	/****************************************************************************
219	 * Private Functions - DMA Software Reset
220	 ****************************************************************************/
221	
222	static int dma_soft_reset(uintptr_t gmac_base)
223	{
224	  uint32_t val;
225	  int timeout = 100000;
226	
227	  val = getreg32(gmac_base + DMA_BUS_MODE);
228	  syslog(LOG_INFO, "sg2000_eth: DMA reset begin bus_mode=0x%08" PRIX32
229	         "\n", val);
230	  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);
231	
232	  do
233	    {
234	      val = getreg32(gmac_base + DMA_BUS_MODE);
235	      if (!(val & DMA_SFT_RESET))
236	        {
237	          return 0;
238	        }
239	
240	      up_udelay(10);
241	    }
242	  while (--timeout > 0);
243	
244	  syslog(LOG_ERR, "sg2000_eth: DMA reset timeout bus_mode=0x%08" PRIX32
245	         " hw_feature0=0x%08" PRIX32 "\n",
246	         getreg32(gmac_base + DMA_BUS_MODE),
247	         getreg32(gmac_base + GMAC_HW_FEATURE0));
248	  return -1;
249	}
